import express from 'express';
import { createRateLimit } from '../../src/middleware/rate-limit';
import { cache } from '../../src/lib/cache';

// Mock the cache module
jest.mock('../../src/lib/cache');
const mockCache = cache as jest.Mocked<typeof cache>;

describe('Rate Limiting Middleware', () => {
  let app: express.Application;

  beforeEach(() => {
    app = express();
    app.set('trust proxy', 1);
    jest.clearAllMocks();
  });

  it('should allow requests under the limit', async () => {
    mockCache.incr.mockResolvedValue(1);
    mockCache.expire.mockResolvedValue(true);

    const rateLimiter = createRateLimit({ max: 5, windowMs: 60000 });
    app.use(rateLimiter);
    app.get('/test', (req, res) => res.json({ success: true }));

    const response = await request(app).get('/test');

    expect(response.status).toBe(200);
    expect(response.headers['x-ratelimit-limit']).toBe('5');
    expect(response.headers['x-ratelimit-remaining']).toBe('4');
  });

  it('should block requests over the limit', async () => {
    mockCache.incr.mockResolvedValue(6);

    const rateLimiter = createRateLimit({ max: 5, windowMs: 60000 });
    app.use(rateLimiter);
    app.get('/test', (req, res) => res.json({ success: true }));

    const response = await request(app).get('/test');

    expect(response.status).toBe(429);
    expect(response.body.error).toContain('Too many requests');
    expect(response.headers['x-ratelimit-remaining']).toBe('0');
  });

  it('should use userId for authenticated requests', async () => {
    mockCache.incr.mockResolvedValue(1);
    mockCache.expire.mockResolvedValue(true);

    const rateLimiter = createRateLimit();
    app.use((req, res, next) => {
      (req as any).userId = 'user123';
      next();
    });
    app.use(rateLimiter);
    app.get('/test', (req, res) => res.json({ success: true }));

    await request(app).get('/test');

    expect(mockCache.incr).toHaveBeenCalledWith(
      expect.stringContaining('user123')
    );
  });

  it('should fail open on Redis errors', async () => {
    mockCache.incr.mockRejectedValue(new Error('Redis connection failed'));

    const rateLimiter = createRateLimit();
    app.use(rateLimiter);
    app.get('/test', (req, res) => res.json({ success: true }));

    const response = await request(app).get('/test');

    expect(response.status).toBe(200);
  });
});
)
